<?php require_once '../config/db.php'; require_once '../includes/auth.php'; require_role('faculty');$st=$pdo->prepare("SELECT * FROM users WHERE id=?");$st->execute([$_SESSION['user_id']]);$u=$st->fetch();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$pdo->prepare("UPDATE users SET name=?,email=? WHERE id=?")->execute([$name,$email,$u['id']]);$_SESSION['name']=$name;$u['name']=$name;$u['email']=$email;$msg='Profile updated.';}$page_title='Profile';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='faculty';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Profile</h1><div class="profile-box"><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><form method="post"><label>Name</label><input name="name" value="<?=e($u['name'])?>" required><label>Email</label><input type="email" name="email" value="<?=e($u['email'])?>" required><button class="btn primary">Update Profile</button></form></div></main></div><?php include '../includes/footer.php';?>